CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid,_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text IN ('comercial','marketing','administracao','desenvolvimento')) AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text IN ('master','senior')) THEN false WHEN _permission IN ('users.update','users.reset','users.promote','users.demote','roles.manage','admins.invite','admins.remove') THEN public.is_master(_user_id) WHEN _permission='finance.read' THEN public.can_read_finance(_user_id) WHEN _permission IN ('finance.settle','finance.release') THEN public.can_write_finance(_user_id) WHEN _permission='ads.manage' THEN public.is_admin_or_master(_user_id) OR public.can_write_finance(_user_id) WHEN _permission='settings.manage' THEN EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text IN ('senior','master')) WHEN _permission IN ('users.read','reports.read','audit_logs.read') THEN public.is_admin_or_master(_user_id) WHEN _permission IN ('submit','approve','edit','delete','events.create','events.read','events.update','events.approve','events.cancel','events.delete') THEN public.is_admin_or_master(_user_id) OR (NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text='financeiro') AND EXISTS(SELECT 1 FROM public.collaborators c WHERE c.user_id=_user_id AND c.is_active AND ((_permission IN ('submit','events.create') AND c.can_submit) OR (_permission IN ('approve','events.approve') AND c.can_approve) OR (_permission IN ('edit','events.update') AND c.can_edit) OR (_permission IN ('delete','events.delete') AND c.can_delete) OR _permission='events.read'))) ELSE false END $$;
CREATE OR REPLACE FUNCTION public.can_create_events(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id IS NOT NULL AND (public.is_admin_or_master(_user_id) OR (NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text IN ('financeiro','comercial','marketing','administracao','desenvolvimento')) AND (EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_user_id AND lower(coalesce(user_type,'')) IN ('divulgador','promotor')) OR EXISTS(SELECT 1 FROM public.collaborators WHERE user_id=_user_id AND is_active AND can_submit)))) $$;
CREATE OR REPLACE FUNCTION public.can_write_finance(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_user IS NOT NULL AND (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user AND role::text IN ('master','senior')) OR (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user AND role::text='financeiro') AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user AND role::text IN ('comercial','marketing','administracao','desenvolvimento')))); $$;
CREATE OR REPLACE FUNCTION public.guard_intranet_campaign() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.destination)>2000 OR NEW.destination !~ '^https://[^/@[:space:]]+([/:?#]|$)' THEN RAISE EXCEPTION 'Informe um link HTTPS válido sem credenciais'; END IF; IF TG_OP='UPDATE' AND NEW.clicks IS DISTINCT FROM OLD.clicks AND current_setting('app.intranet_click',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'Contadores são controlados pelo servidor'; END IF; IF TG_OP='INSERT' THEN NEW.clicks:=0; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_intranet_campaign BEFORE INSERT OR UPDATE ON public.intranet_campaigns FOR EACH ROW EXECUTE FUNCTION public.guard_intranet_campaign();
CREATE OR REPLACE FUNCTION public.intranet_open_campaign(p_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE destination_url text; BEGIN PERFORM set_config('app.intranet_click','yes',true); UPDATE public.intranet_campaigns SET clicks=clicks+1 WHERE id=p_id AND status='ativa' RETURNING destination INTO destination_url; RETURN destination_url; END $$;